package core

import (
	"github.com/jokruger/kavun/core/member"
	"github.com/jokruger/kavun/internal/text"
)

// rune's members: one function per member, each declared by the //kavun:member directive in its doc comment. The table,
// runeMethods, and the member entries of docs/reference/types/rune.md (alphabetical, so the order here is free) are
// generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// Total on every rune; the default verb is the symbol itself:
//
// ```go
// 'є'.format()       // => "є" — default verb is c
// 'є'.format("d")    // => "1108" — the code point in decimal
// 'є'.format("x")    // => "454" — hex, no 0x prefix on runes
// 'є'.format("U")    // => "U+0454" — the U+ notation
// 'є'.format("q")    // => "'є'" — quoted literal
// ```
//
//kavun:member format pure ([spec]) -> string
func runeFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Report truthiness: NUL is falsy (`!!x` ⟺ `x != rune()`).
//
// ```go
// '\x00'.is_true()   // => false
// 'a'.is_true()      // => true
// ```
//
//kavun:member is_true pure () -> bool
func runeIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Answer the receiver — a `rune` is always immutable.
//
// Identity no-ops on an immutable scalar — kept so generic code never type-errors:
//
// ```go
// 'a'.copy()     // => 'a'
// 'a'.freeze()   // => 'a'
// ```
//
//kavun:member copy pure () -> rune
func runeCopy(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver — a `rune` is always immutable; see [`copy`](#copy).
//
//kavun:member freeze pure () -> rune
func runeFreeze(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver, the identity conversion.
//
//kavun:member rune pure ([default]) -> rune
func runeRune(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), runeTypeName, args, true, v)
}

// Answer the code point's value.
//
// ```go
// 'A'.int()          // => 65
// 'є'.int()          // => 1108
// ```
//
//kavun:member int pure ([default]) -> int
func runeInt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), runeTypeName, args, true, IntValue(int64(v.Data)))
}

// Convert to the same symbol as one octet; a rune that is neither ASCII nor an escape raises unless a default is given.
//
// ```go
// 'A'.byte()         // => byte(65)
// 'є'.byte()         // Error: conversion: cannot convert rune to byte
// 'є'.byte(b'?')     // => byte(63) — the default covers the partial edge
// ```
//
//kavun:member byte pure ([default]) -> byte
func runeByte(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	b, ok := v.AsByte()
	return ConvMember(id.String(), runeTypeName, args, ok, ByteValue(b))
}

// Answer the symbol as text; an escape answers its octet.
//
// ```go
// 'A'.string()       // => "A"
// 'є'.string()       // => "є" — every code point has a text form
// ```
//
//kavun:member string pure ([default]) -> string
func runeString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// total — the default slot never fires, but every conversion carries it. An escape rune
	// answers the single octet it stands for, so it round-trips back to the data it came from
	return ConvMember(id.String(), runeTypeName, args, true, NewStringValue(text.EncodeRuneText(rune(v.Data))))
}

// Answer the symbol as `runes`; see [`string`](#string).
//
// ```go
// 'є'.runes()        // => u"є" — the text targets compose through string
// ```
//
//kavun:member runes pure ([default]) -> runes
func runeRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), runeTypeName, args, true, NewRunesValue([]rune{rune(v.Data)}, false))
}

// Report whether this is a real symbol rather than an octet escape.
//
//kavun:member is_valid pure () -> bool
func runeIsValid(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return BoolValue(text.RuneIsValid(rune(v.Data))), nil
}

// Report whether the code point is below `U+0080`.
//
//kavun:member is_ascii pure () -> bool
func runeIsASCII(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return BoolValue(rune(v.Data) < 0x80), nil
}
